import sys, os; sys.path.insert(0, os.path.dirname(os.path.dirname(__file__)))
from dsl import *
U("s1-u06")

L(1, "Países", "Os nomes dos países vizinhos e de língua portuguesa.",
  ["Dizer nomes de países", "Dizer de onde vem e onde vive alguém"],
  vocab=[V("v-land","land","país","noun","het","landen"), V("v-spanje","Spanje","Espanha","noun"),
         V("v-frankrijk","Frankrijk","França","noun"), V("v-duitsland","Duitsland","Alemanha","noun"),
         V("v-belgie","België","Bélgica","noun"), V("v-brazilie","Brazilië","Brasil","noun"),
         V("v-engeland","Engeland","Inglaterra","noun")],
  ex=[("Ik kom uit Portugal.","Sou de Portugal."),("Zij woont in Spanje.","Ela vive em Espanha."),("België is klein.","A Bélgica é pequena.")],
  gram=[G("g-paises-sem-artigo","Países sem artigo","Em neerlandês a maioria dos países **não leva artigo**: *in Spanje*, *uit Frankrijk*, *België is klein*. Exceções com artigo: **de Verenigde Staten** (os EUA) e **het Verenigd Koninkrijk** (o Reino Unido).",
    [("Ik woon in Duitsland.","Vivo na Alemanha."),("Hij komt uit Brazilië.","Ele é do Brasil.")],
    "Em português dizemos «a França», «o Brasil», «na Alemanha»; em neerlandês, sem artigo.")],
  review=["v-komen-uit","v-wonen","v-in","v-portugal","v-nederland"],
  exs=[
    MA([("Spanje","Espanha"),("Frankrijk","França"),("Duitsland","Alemanha"),("België","Bélgica"),("Brazilië","Brasil")], "Países frequentes.", ["v-spanje","v-frankrijk","v-duitsland","v-belgie","v-brazilie"]),
    TR("pt-nl","Ela vive em Espanha.", ["[Zij|Ze] woont in Spanje"], "Sem artigo antes do país.", ["v-spanje","v-wonen"], bank=["Zij","woont","in","Spanje","de","komt"]),
    TR("nl-pt","Hij komt uit Brazilië.", ["(Ele )é do Brasil","(Ele )vem do Brasil"], "komen uit = ser de / vir de.", ["v-brazilie","v-komen-uit"]),
    FE(["Ik","woon","in","de","Frankrijk."], 3, "(retirar)", "Os países não levam artigo: «in Frankrijk».", ["v-frankrijk"]),
    AR("land","o país","het", "«Het land» — plural «landen».", ["v-land"]),
    MC("Qual destes países leva artigo em neerlandês?", ["*de Verenigde Staten","Duitsland|Não leva artigo.","Spanje|Não leva artigo."], "Os EUA e o Reino Unido são exceções com artigo.", ["v-land"]),
    LI("Ik woon in België.", ["Ik woon in België"], "Vivo na Bélgica.", "O «ë» indica que se lê uma nova sílaba: Bel-gi-ë.", ["v-belgie"]),
    FB("Mijn vriend komt uit ___.", ["Engeland"], "uit + país sem artigo.", ["v-engeland"], choices=["Engeland","Engels","de Engeland"], tr="O meu amigo é de Inglaterra."),
    WO("A Alemanha é grande.", ["Duitsland","is","groot"], "Sem artigo antes do país.", ["v-duitsland","v-groot"]),
    TR("nl-pt","Nederland is een klein land.", ["(Os )Países Baixos são um país pequeno","A Holanda é um país pequeno"], "«een klein land»: o adjetivo antes do nome — explicação na Secção 2.", ["v-land","v-nederland","v-klein"]),
  ], diff=1, mins=5)

L(2, "Nacionalidades", "Ik ben Portugees, zij is Portugese.",
  ["Dizer a nacionalidade, no masculino e no feminino"],
  vocab=[V("v-portugees","Portugees","português","adjective",note="Feminino: Portugese. Ik ben Portugees / Portugese."),
         V("v-nederlander","Nederlander","neerlandês (pessoa)","noun","de","Nederlanders",note="Uma neerlandesa: een Nederlandse."),
         V("v-spaans-adj","Spaans","espanhol","adjective",note="Pessoa: een Spanjaard / een Spaanse."),
         V("v-duits-adj","Duits","alemão","adjective",note="Pessoa: een Duitser / een Duitse."),
         V("v-belg","Belg","belga","noun","de","Belgen",note="Feminino: een Belgische."),
         V("v-braziliaans","Braziliaans","brasileiro","adjective",note="Pessoa: een Braziliaan / een Braziliaanse.")],
  ex=[("Ik ben Portugees.","Sou português."),("Zij is Portugese.","Ela é portuguesa."),("Tom is Nederlander.","O Tom é neerlandês."),("Eva is een Nederlandse.","A Eva é neerlandesa.")],
  gram=[G("g-nacionalidades","Nacionalidades","Para dizer a nacionalidade usa-se **zijn** + adjetivo ou substantivo: *Ik ben Portugees* (m), *ik ben Portugese* (f). Muitas têm um substantivo próprio para homem e outro para mulher: **Nederlander / Nederlandse**, **Duitser / Duitse**, **Spanjaard / Spaanse**. As nacionalidades escrevem-se com **maiúscula**.",
    [("Hij is Duitser.","Ele é alemão."),("Zij is Duitse.","Ela é alemã.")],
    "Em português escrevemos «português» com minúscula; em neerlandês, «Portugees» leva maiúscula.")],
  review=["v-portugal","v-nederland","v-duitsland","v-spanje"],
  exs=[
    MC("Como diz uma mulher «Sou portuguesa»?", ["*Ik ben Portugese.","Ik ben Portugees.|É a forma masculina.","Ik ben Portugal.|Isso seria «Sou Portugal»."], "Feminino: Portugese.", ["v-portugees"]),
    MA([("Nederlander","neerlandês"),("Belg","belga"),("Duitser","alemão"),("Spanjaard","espanhol")], "Substantivos de nacionalidade (masculino).", ["v-nederlander","v-belg","v-duits-adj","v-spaans-adj"]),
    TR("pt-nl","Sou português.", ["Ik ben Portugees"], "Maiúscula na nacionalidade.", ["v-portugees"]),
    TR("nl-pt","Zij is Nederlandse.", ["(Ela )é neerlandesa","(Ela )é holandesa"], "Nederlandse = neerlandesa.", ["v-nederlander"]),
    FB("Hij komt uit Duitsland. Hij is ___.", ["Duitser"], "Homem da Alemanha: Duitser.", ["v-duits-adj"], choices=["Duitser","Duitse","Duitsland"], tr="Ele é da Alemanha. É alemão."),
    FE(["Ik","ben","Portugal."], 2, "Portugees", "Para a nacionalidade usa-se «Portugees»; «Portugal» é o país. (E as nacionalidades escrevem-se com maiúscula.)", ["v-portugees"]),
    LI("Ik ben Portugees.", ["Ik ben Portugees"], "Sou português.", "«ee» longo no fim: Por-tu-gees.", ["v-portugees"]),
    DL([("Eva","Ben jij Spaans?","És espanhol?"),("Pedro","")], ["*Nee, ik ben Portugees.","Nee, ik ben Portugal.|Portugal é o país; a nacionalidade é Portugees.","Ja, ik kom uit Portugal.|«Ja» contradiz o resto da frase."], "Nacionalidade: Portugees.", ["v-portugees"]),
    WO("Ela é belga, não é francesa.", ["Ze","is","Belgische,","geen","Française"], "«geen» nega substantivos — veremos mais tarde.", ["v-belg"]),
    CO("text","Na aula de neerlandês", "In de klas zijn vijf studenten. Ana is Portugese en Pedro is Braziliaan. Lukas is Duitser. Marie is Belgische en Carlos is Spanjaard.",
       [("De onde é o Pedro?", ["*Do Brasil","De Portugal","De Espanha"]),("Quem é belga?", ["*A Marie","A Ana","O Lukas"])],
       "Repare nas formas masculinas e femininas.", ["v-braziliaans","v-belg"]),
  ], diff=2, mins=6)

L(3, "Que línguas falas?", "spreken e os nomes das línguas.",
  ["Dizer que línguas fala e quão bem", "Perguntar a alguém que línguas fala"],
  vocab=[V("v-spreken","spreken","falar","verb",note="ik spreek, jij spreekt"), V("v-engels","Engels","inglês","noun","het",note="A língua."),
         V("v-spaans-taal","Spaans","espanhol (língua)","noun","het"), V("v-frans","Frans","francês","noun","het"),
         V("v-portugees-taal","Portugees","português (língua)","noun","het"), V("v-een-beetje","een beetje","um pouco","expression"),
         V("v-taal","taal","língua","noun","de","talen")],
  ex=[("Ik spreek Portugees en Engels.","Falo português e inglês."),("Ik spreek een beetje Nederlands.","Falo um pouco de neerlandês."),("Spreekt u Engels?","Fala inglês?")],
  gram=[G("g-spreken","Spreken","**spreken**: ik spreek, jij spreekt, u spreekt, hij spreekt, wij spreken. Os nomes das línguas são neutros (**het** Nederlands) e escrevem-se com maiúscula. Na pergunta com «jij», o -t cai: **Spreek jij Frans?**",
    [("Spreek je Nederlands?","Falas neerlandês?"),("Een beetje.","Um pouco.")],
    "Em português diz-se «falar um pouco DE neerlandês»; em neerlandês não há preposição: een beetje Nederlands.")],
  review=["v-nederlands","v-en","v-maar"],
  exs=[
    MA([("Engels","inglês"),("Frans","francês"),("een beetje","um pouco"),("taal","língua")], "Línguas e expressões.", ["v-engels","v-frans","v-een-beetje","v-taal"]),
    CJ("spreken","ik","Ik ___ Portugees.", ["spreek"], "Raiz: spreek (o «ee» longo mantém-se).", ["v-spreken"]),
    CJ("spreken","u","___ u Engels?", ["Spreekt"], "Com «u»: spreekt — também na pergunta.", ["v-spreken"]),
    TR("pt-nl","Falo um pouco de neerlandês.", ["Ik spreek een beetje Nederlands"], "Sem «de»: een beetje Nederlands.", ["v-spreken","v-een-beetje"], bank=["Ik","spreek","een","beetje","Nederlands","van","spreekt"]),
    TR("nl-pt","Spreek jij Frans?", ["Falas francês"], "Pergunta com o verbo primeiro; o -t cai antes de «jij».", ["v-spreken","v-frans"]),
    FE(["Ik","spreek","een","beetje","van","Nederlands."], 4, "(retirar)", "Não se usa «van»: een beetje Nederlands.", ["v-een-beetje"]),
    AR("taal","a língua","de", "«De taal» — plural «talen».", ["v-taal"]),
    DL([("Turista","Pardon, spreekt u Engels?","Desculpe, fala inglês?"),("Funcionário","")], ["*Ja, natuurlijk.","Ja, ik ben Engels.|Perguntaram se fala, não de onde é.","Nee, ik ben moe.|Não responde à pergunta."], "«Natuurlijk» = claro.", ["v-spreken","v-engels"]),
    LI("Spreekt u Nederlands?", ["Spreekt u Nederlands"], "Fala neerlandês?", "Pergunta formal.", ["v-spreken","v-nederlands"]),
    SW("Diga que línguas fala e quão bem (pelo menos duas).", ["Ik spreek Portugees en Engels","Ik spreek Portugees(,) Engels en een beetje Nederlands"],
       ["Usa «ik spreek»","Liga as línguas com «en»","Línguas com maiúscula"], 4, "Modelo: «Ik spreek Portugees, Engels en een beetje Nederlands.»", ["v-spreken","v-een-beetje"]),
  ], diff=2, mins=6)

L(4, "Cidades e lugares", "Cidade, aldeia, capital, perto e longe.",
  ["Falar da cidade onde vive", "Dizer se um lugar é perto ou longe"],
  vocab=[V("v-stad","stad","cidade","noun","de","steden"), V("v-dorp","dorp","aldeia","noun","het","dorpen"),
         V("v-hoofdstad","hoofdstad","capital","noun","de"), V("v-ver","ver","longe","adjective"),
         V("v-dichtbij","dichtbij","perto","adverb"), V("v-van","van","de","preposition",note="Origem ou posse: de hoofdstad van Portugal.")],
  ex=[("Lissabon is de hoofdstad van Portugal.","Lisboa é a capital de Portugal."),("Amsterdam is de hoofdstad van Nederland.","Amesterdão é a capital dos Países Baixos."),("Is het ver?","É longe?")],
  gram=[G("g-hoofdstad","A capital","**Amsterdam** é a capital dos Países Baixos, mas o governo e o parlamento ficam em **Den Haag** (Haia). **Van** liga nomes como o nosso «de»: *de hoofdstad van Portugal*.",
    [("Den Haag is niet de hoofdstad.","Haia não é a capital."),("Utrecht is dichtbij.","Utrecht é perto.")])],
  review=["v-wonen","v-in","v-groot","v-klein","v-mooi"],
  exs=[
    MA([("stad","cidade"),("dorp","aldeia"),("hoofdstad","capital"),("ver","longe"),("dichtbij","perto")], "Lugares e distâncias.", ["v-stad","v-dorp","v-hoofdstad","v-ver","v-dichtbij"]),
    MC("Qual é a capital dos Países Baixos?", ["*Amsterdam","Den Haag|O governo fica em Haia, mas a capital é Amesterdão.","Rotterdam|É a segunda maior cidade."], "Amsterdam é a capital; Den Haag é a sede do governo.", ["v-hoofdstad"]),
    AR("dorp","a aldeia","het", "«Het dorp».", ["v-dorp"]),
    AR("stad","a cidade","de", "«De stad» — plural irregular «steden».", ["v-stad"]),
    TR("pt-nl","Lisboa é a capital de Portugal.", ["Lissabon is de hoofdstad van Portugal"], "«van» = de.", ["v-hoofdstad","v-van"]),
    TR("nl-pt","Is het ver?", ["É longe"], "«het» como sujeito vazio, tal como «het is koud».", ["v-ver"]),
    FB("Utrecht is niet ver, het is ___.", ["dichtbij"], "ver ≠ dichtbij.", ["v-dichtbij"], choices=["dichtbij","groot","stad"], tr="Utrecht não é longe, é perto."),
    LI("Ik woon in een klein dorp.", ["Ik woon in een klein dorp"], "Vivo numa aldeia pequena.", "«een klein dorp»: com «het»-palavras o adjetivo não leva -e depois de «een».", ["v-dorp","v-klein"]),
    WO("A cidade é bonita, mas é longe.", ["De","stad","is","mooi,","maar","het","is","ver"], "«maar» liga duas frases sem mudar a ordem.", ["v-stad","v-ver","v-maar"]),
    CO("text","Onde vive a Marta?", "Marta woont in Leiden. Leiden is een mooie stad. Het is niet ver van Den Haag en Amsterdam is ook dichtbij.",
       [("Como é Leiden?", ["*Bonita","Muito grande","Longe de tudo"]),("Amesterdão fica…", ["*perto","longe","na Bélgica"])],
       "«niet ver» = não é longe; «ook dichtbij» = também perto.", ["v-stad","v-dichtbij","v-ver"]),
  ], diff=2, mins=6)

L(5, "De onde és e que línguas falas?", "Revisão: país, nacionalidade, língua e cidade numa conversa.",
  ["Apresentar-se com origem, nacionalidade e línguas"],
  ex=[("Ik ben Portugees, ik kom uit Porto en ik woon nu in Utrecht.","Sou português, sou do Porto e agora vivo em Utrecht.")],
  review=["v-portugees","v-spreken","v-stad","v-komen-uit","v-wonen","v-een-beetje","v-land","v-taal"],
  exs=[
    DL([("Sanne","Waar kom je vandaan?","De onde és?"),("Ana","Uit Portugal. Ik ben Portugese.","De Portugal. Sou portuguesa."),("Sanne","Welke talen spreek je?","Que línguas falas?"),("Ana","")], ["*Portugees, Engels en een beetje Nederlands.","Ik ben Lissabon.|Não responde à pergunta.","Ik woon in Leiden.|Perguntaram as línguas."], "«Welke talen?» = que línguas?", ["v-spreken","v-taal"]),
    TR("pt-nl","Sou portuguesa e vivo em Roterdão.", ["Ik ben Portugese en ik woon in Rotterdam"], "Feminino: Portugese.", ["v-portugees","v-wonen"]),
    MC("O Carlos é de Madrid. Ele é…", ["*Spanjaard","Spaans|«Spaans» é a língua (ou adjetivo); a pessoa é «Spanjaard».","Spanje|É o país."], "País Spanje, língua Spaans, pessoa Spanjaard.", ["v-spaans-adj"]),
    MA([("Duitsland","Alemanha"),("Duits","alemão (língua)"),("Frankrijk","França"),("Frans","francês (língua)")], "País e língua.", ["v-duitsland","v-duits-adj","v-frankrijk","v-frans"]),
    TR("nl-pt","Welke talen spreek je?", ["Que línguas falas"], "«welke» = que/quais.", ["v-taal","v-spreken"]),
    FE(["Zij","komt","uit","Duits."], 3, "Duitsland", "Depois de «uit» vem o país: Duitsland.", ["v-duitsland"]),
    LI("Ik spreek een beetje Nederlands.", ["Ik spreek een beetje Nederlands"], "Falo um pouco de neerlandês.", "Frase muito útil!", ["v-een-beetje"]),
    CO("text","Um novo colega", "Mijn nieuwe collega heet Lukas. Hij is Duitser, maar hij woont al tien jaar in Nederland. Hij spreekt Duits, Engels en heel goed Nederlands.",
       [("Qual é a nacionalidade do Lukas?", ["*Alemã","Neerlandesa","Inglesa"]),("Como é o neerlandês dele?", ["*Muito bom","Fraco","Não fala neerlandês"])],
       "«al tien jaar» = há dez anos.", ["v-spreken","v-duits-adj"]),
    SW("Apresente-se: nacionalidade, cidade onde vive e línguas que fala.", ["Ik ben [Portugees|Portugese](.) Ik woon in Lissabon(.) Ik spreek Portugees en Engels"],
       ["Nacionalidade com «ik ben»","Cidade com «ik woon in»","Línguas com «ik spreek»"], 8, "Modelo: «Ik ben Portugees. Ik woon in Lissabon. Ik spreek Portugees en Engels.»", ["v-portugees","v-spreken"]),
  ], diff=2, mins=7)

W()
